var o=`gang-of-four-gof-design-patterns`;var r=21;var i={en:[{id:`T021-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`Gang of Four (GoF) Design Patterns`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`A Repository presents a collection-like interface for domain objects and hides persistence operations.`},{id:`B`,text:`Adapter translates one interface into another expected by a client.`},{id:`C`,text:`The 23 GoF patterns describe recurring object collaboration and creation solutions.`},{id:`D`,text:`MVC, MVP and MVVM are presentation architecture patterns that separate visual behavior from domain logic in different ways.`}]},{id:`T021-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`Gang of Four (GoF) Design Patterns`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Adapter performs mapping between contracts, types and error semantics; Facade coordinates several calls into common workflows.`},{id:`B`,text:`Creational patterns include Factory Method, Abstract Factory, Builder, Prototype and Singleton; structural ones include Adapter, Bridge, Composite, Decorator, Facade, Flyweight and Proxy; behavioral ones include Strategy, Observer, Command, State, Template Method, Iterator, Mediator, Memento, Chain of Responsibility, Visitor and Interpreter.`},{id:`C`,text:`Design operations around use cases or aggregates, such as findAvailableRooms and saveReservation.`},{id:`D`,text:`MVC routes input through controllers and models; MVP uses a presenter to drive a more passive view; MVVM exposes view state and commands for binding.`}]},{id:`T021-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`A team faces this situation: `},{t:`An editor might use Command for undo, Observer for document updates, and Strategy for export formats.`,b:!0},{t:` What is the most appropriate response?`}]}],options:[{id:`A`,text:`An Order knows its line items, so it can calculate a subtotal as Information Expert; an application controller orchestrates checkout without implementing all pricing rules; a repository is a Pure Fabrication serving persistence needs.`},{id:`B`,text:`The UI reacts to order-state changes through observers, while the pricing domain need not know about components.`},{id:`C`,text:`These patterns solve different pressures; a single large 'pattern framework' adds little value.`},{id:`D`,text:`A booking repository ensures reservation records are retrieved and saved consistently, while a report query reads optimized projections without loading rich aggregates.`}]},{id:`T021-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`Gang of Four (GoF) Design Patterns`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`Observer can create hidden dependencies, duplicate notifications and memory leaks.`},{id:`B`,text:`GoF examples predate modern languages and frameworks.`},{id:`C`,text:`State classes are unnecessary for trivial two-state toggles; a transition table may suffice.`},{id:`D`,text:`Information Expert alone can create overly large domain objects; balance it with cohesion and coupling. 'Controller' in GRASP means use-case coordination, not necessarily an MVC HTTP controller.`}]},{id:`T021-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`They group into creational, structural, and behavioral patterns; learning their intent matters more than memorizing UML diagrams.`}]}]},{id:`T021-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`Every Gang of Four pattern should be introduced into every codebase.`}]}]},{id:`T021-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`Built-in functions, closures, modules, and dependency injection often express the same ideas more simply; do not force class hierarchies.`}]}]},{id:`T021-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`Gang of Four (GoF) Design Patterns`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`The 23 GoF patterns describe recurring object collaboration and creation solutions.`},{id:`B`,text:`Creational patterns include Factory Method, Abstract Factory, Builder, Prototype and Singleton; structural ones include Adapter, Bridge, Composite, Decorator, Facade, Flyweight and Proxy; behavioral ones include Strategy, Observer, Command, State, Template Method, Iterator, Mediator, Memento, Chain of Responsibility, Visitor and Interpreter.`},{id:`C`,text:`A pattern name is proof a design is correct regardless of context.`},{id:`D`,text:`MVC, MVP and MVVM prescribe exactly the same UI dependency direction.`}]},{id:`T021-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`Gang of Four (GoF) Design Patterns`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`These patterns solve different pressures; a single large 'pattern framework' adds little value.`},{id:`B`,text:`Built-in functions, closures, modules, and dependency injection often express the same ideas more simply; do not force class hierarchies.`},{id:`C`,text:`Every Gang of Four pattern should be introduced into every codebase.`},{id:`D`,text:`Repository abstractions should copy every driver-specific operation verbatim.`}]},{id:`T021-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`An editor might use Command for undo, Observer for document updates, and Strategy for export formats.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Ask an agent to add a pricing strategy and order-status observer. Require unsubscribe handling, deterministic tests, and a note explaining why each pattern was selected.`},{id:`B`,text:`Give an agent three changing requirements for a document editor. Ask it to choose at most two patterns, explain alternatives, and demonstrate how the design accommodates an added feature.`},{id:`C`,text:`Ask an agent to assign ownership for pricing, payment, receipt and inventory operations in checkout. For each owner, require a GRASP rationale and compare one rejected placement.`},{id:`D`,text:`Have an agent model a reservation transition matrix and implement cancel and confirm commands. Reject invalid transitions, test concurrent commands, and describe any undo semantics.`}]},{id:`T021-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`How do you tell pattern recognition from pattern-driven overengineering?`}]}]},{id:`T021-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`An editor might use Command for undo, Observer for document updates, and Strategy for export formats.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`Gang of Four (GoF) Design Patterns`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T021-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`An editor might use Command for undo, Observer for document updates, and Strategy for export formats.`,b:!0},{t:` — propose three checks for `},{t:`Gang of Four (GoF) Design Patterns`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T021-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`An editor might use Command for undo, Observer for document updates, and Strategy for export formats.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T021-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`Gang of Four (GoF) Design Patterns`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`An editor might use Command for undo, Observer for document updates, and Strategy for export formats.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T021-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Патерни проєктування Gang of Four`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Repository надає інтерфейс, схожий на колекцію доменних об’єктів, і приховує операції збереження.`},{id:`B`,text:`Adapter перетворює один інтерфейс на інший, який очікує клієнт.`},{id:`C`,text:`23 патерни GoF описують типові рішення створення об’єктів та їх співпраці.`},{id:`D`,text:`MVC, MVP та MVVM — патерни архітектури представлення, які по-різному відділяють UI від бізнес-логіки.`}]},{id:`T021-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Патерни проєктування Gang of Four`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Adapter виконує мапінг контрактів, типів і помилок; Facade координує кілька викликів у типових сценаріях.`},{id:`B`,text:`Породжувальні: Factory Method, Abstract Factory, Builder, Prototype, Singleton; структурні: Adapter, Bridge, Composite, Decorator, Facade, Flyweight, Proxy; поведінкові: Strategy, Observer, Command, State, Template Method, Iterator, Mediator, Memento, Chain of Responsibility, Visitor, Interpreter.`},{id:`C`,text:`Проєктуйте операції навколо сценаріїв або агрегатів, наприклад findAvailableRooms і saveReservation.`},{id:`D`,text:`MVC обробляє ввід через контролери й моделі; MVP використовує presenter, що керує пасивнішим view; MVVM відкриває стан і команди для binding.`}]},{id:`T021-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Команда має таку ситуацію: `},{t:`Редактор може застосувати Command для undo, Observer для оновлення документа й Strategy для форматів експорту.`,b:!0},{t:` Яке рішення найдоречніше?`}]}],options:[{id:`A`,text:`Order знає свої позиції, тому обчислення підсумку може належати йому як Information Expert; контролер застосунку керує checkout, але не містить усіх правил цін; репозиторій — Pure Fabrication для роботи зі сховищем.`},{id:`B`,text:`UI реагує на стан замовлення через спостерігачів, а домен цін нічого не знає про компоненти.`},{id:`C`,text:`Патерни вирішують різні задачі; один великий «фреймворк патернів» не приносить користі.`},{id:`D`,text:`Репозиторій бронювань узгоджено завантажує й зберігає записи, тоді як сервіс звітів читає оптимізовані проєкції без створення повних агрегатів.`}]},{id:`T021-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Патерни проєктування Gang of Four`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Observer може створювати приховані залежності, дублікати повідомлень та витоки пам’яті.`},{id:`B`,text:`Приклади GoF створені до багатьох сучасних мов і фреймворків.`},{id:`C`,text:`Класи State зайві для простого перемикача з двома станами; іноді достатньо таблиці переходів.`},{id:`D`,text:`Information Expert сам по собі може створити надто великі сутності; урівноважуйте його згуртованістю та зв’язністю.`}]},{id:`T021-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Вони поділяються на породжувальні, структурні й поведінкові; важливіше розуміти намір, ніж завчати UML-діаграми.`}]}]},{id:`T021-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`Кожен патерн GoF потрібно впровадити в кожну кодову базу.`}]}]},{id:`T021-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Функції, замикання, модулі й DI часто виражають ті самі ідеї простіше; не нав’язуйте ієрархії класів.`}]}]},{id:`T021-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Патерни проєктування Gang of Four`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`23 патерни GoF описують типові рішення створення об’єктів та їх співпраці.`},{id:`B`,text:`Породжувальні: Factory Method, Abstract Factory, Builder, Prototype, Singleton; структурні: Adapter, Bridge, Composite, Decorator, Facade, Flyweight, Proxy; поведінкові: Strategy, Observer, Command, State, Template Method, Iterator, Mediator, Memento, Chain of Responsibility, Visitor, Interpreter.`},{id:`C`,text:`Назва патерна сама доводить коректність дизайну незалежно від контексту.`},{id:`D`,text:`MVC, MVP і MVVM задають ідентичний напрям залежностей у UI.`}]},{id:`T021-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Патерни проєктування Gang of Four`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Патерни вирішують різні задачі; один великий «фреймворк патернів» не приносить користі.`},{id:`B`,text:`Функції, замикання, модулі й DI часто виражають ті самі ідеї простіше; не нав’язуйте ієрархії класів.`},{id:`C`,text:`Кожен патерн GoF потрібно впровадити в кожну кодову базу.`},{id:`D`,text:`Абстракції Repository мають дослівно повторювати всі драйвер-специфічні операції.`}]},{id:`T021-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Редактор може застосувати Command для undo, Observer для оновлення документа й Strategy для форматів експорту.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента додати стратегію ціни та спостерігача стану замовлення. Вимагайте відписування, детерміновані тести й пояснення вибору кожного патерну.`},{id:`B`,text:`Дайте агенту три змінні вимоги редактора документів. Попросіть обрати не більше двох патернів, пояснити альтернативи й показати, як додати нову фічу.`},{id:`C`,text:`Попросіть агента розподілити відповідальність за ціни, платежі, квитанції та склад у checkout. Для кожного власника вимагайте обґрунтування через GRASP і порівняння з відхиленим рішенням.`},{id:`D`,text:`Попросіть агента побудувати матрицю переходів бронювання та команди cancel і confirm. Забороніть недійсні переходи, перевірте конкуренцію й опишіть undo.`}]},{id:`T021-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Як відрізнити доречне впізнавання патерну від зайвого ускладнення заради патернів?`}]}]},{id:`T021-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Редактор може застосувати Command для undo, Observer для оновлення документа й Strategy для форматів експорту.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Патерни проєктування Gang of Four`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T021-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Редактор може застосувати Command для undo, Observer для оновлення документа й Strategy для форматів експорту.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Патерни проєктування Gang of Four`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T021-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Редактор може застосувати Command для undo, Observer для оновлення документа й Strategy для форматів експорту.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T021-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Патерни проєктування Gang of Four`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Редактор може застосувати Command для undo, Observer для оновлення документа й Strategy для форматів експорту.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var n={slug:o,topicId:21,questions:i};export{n as default,i as questions,o as slug,r as topicId};